T5="P1-M4-5"; T6="P1-M4-6"
Q=[
# ---------- art. 48 ----------
(T5,["48"],"C","Cabe ao Congresso Nacional, com a sanção do Presidente da República, não exigida esta para o especificado nos arts. 49, 51 e 52, dispor sobre todas as matérias de competência da União.","Art. 48, caput.","leitura"),
(T5,["48"],"E","Cabe ao Congresso Nacional, sem a sanção do Presidente da República, dispor sobre sistema tributário, arrecadação e distribuição de rendas.","Art. 48, I: com a sanção do Presidente (a dispensa vale só para os arts. 49, 51 e 52).","pegadinha"),
(T5,["48"],"C","A concessão de anistia é matéria sobre a qual o Congresso Nacional dispõe com a sanção do Presidente da República.","Art. 48, VIII.","competencia"),
(T5,["48"],"C","A criação e extinção de Ministérios e órgãos da administração pública é matéria sobre a qual o Congresso Nacional dispõe com a sanção do Presidente da República.","Art. 48, XI.","competencia"),
(T5,["48"],"E","A mudança temporária da sede do Congresso Nacional depende de lei sancionada pelo Presidente da República.","Art. 49, VI: competência exclusiva do Congresso Nacional (sem sanção). A transferência da sede do Governo Federal é que se faz por lei (art. 48, VII).","pegadinha"),
(T5,["48"],"C","A fixação do subsídio dos Ministros do Supremo Tribunal Federal é matéria sobre a qual o Congresso Nacional dispõe com a sanção do Presidente da República.","Art. 48, XV.","competencia"),
(T5,["48"],"C","A fixação e modificação do efetivo das Forças Armadas é matéria sobre a qual dispõe o Congresso Nacional, com a sanção do Presidente da República.","Art. 48, III.","competencia"),
# ---------- art. 49 (incisos) ----------
(T5,["49.IV"],"C","Compete exclusivamente ao Congresso Nacional aprovar o estado de defesa e a intervenção federal, autorizar o estado de sítio, ou suspender qualquer uma dessas medidas.","Art. 49, IV.","competencia"),
(T5,["49.VI"],"C","Compete exclusivamente ao Congresso Nacional mudar temporariamente sua sede.","Art. 49, VI.","competencia"),
(T5,["49.VIII"],"C","Compete exclusivamente ao Congresso Nacional fixar os subsídios do Presidente e do Vice-Presidente da República e dos Ministros de Estado.","Art. 49, VIII.","competencia"),
(T5,["49.X"],"C","Compete exclusivamente ao Congresso Nacional fiscalizar e controlar, diretamente, ou por qualquer de suas Casas, os atos do Poder Executivo, incluídos os da administração indireta.","Art. 49, X.","competencia"),
(T5,["49.XI"],"C","Compete exclusivamente ao Congresso Nacional zelar pela preservação de sua competência legislativa em face da atribuição normativa dos outros Poderes.","Art. 49, XI.","competencia"),
(T5,["49.XII"],"C","Compete exclusivamente ao Congresso Nacional apreciar os atos de concessão e renovação de concessão de emissoras de rádio e televisão.","Art. 49, XII.","competencia"),
(T5,["49.XIV"],"C","Compete exclusivamente ao Congresso Nacional aprovar iniciativas do Poder Executivo referentes a atividades nucleares.","Art. 49, XIV.","competencia"),
(T5,["49.XVI"],"C","Compete exclusivamente ao Congresso Nacional autorizar, em terras indígenas, a exploração e o aproveitamento de recursos hídricos e a pesquisa e lavra de riquezas minerais.","Art. 49, XVI.","competencia"),
(T5,["49.XVII"],"C","Compete exclusivamente ao Congresso Nacional aprovar, previamente, a alienação ou concessão de terras públicas com área superior a dois mil e quinhentos hectares.","Art. 49, XVII.","numero"),
(T5,["49.XVIII"],"C","Compete exclusivamente ao Congresso Nacional decretar o estado de calamidade pública de âmbito nacional previsto nos arts. 167-B a 167-G da Constituição.","Art. 49, XVIII.","competencia"),
(T5,["49.IX"],"E","Compete exclusivamente ao Senado Federal julgar anualmente as contas prestadas pelo Presidente da República.","Art. 49, IX: competência do Congresso Nacional.","competencia"),
# ---------- arts. 51 e 52 ----------
(T5,["51"],"C","Compete privativamente à Câmara dos Deputados eleger membros do Conselho da República, nos termos do art. 89, VII.","Art. 51, V.","competencia"),
(T5,["52.III"],"C","Compete privativamente ao Senado Federal aprovar previamente, por voto secreto, após arguição pública, a escolha de presidente e diretores do Banco Central.","Art. 52, III, d.","competencia"),
(T5,["52.III"],"E","A escolha do Procurador-Geral da República é aprovada previamente pelo Senado Federal, por voto aberto, após arguição pública.","Art. 52, III, e: por voto secreto, após arguição pública.","pegadinha"),
(T5,["52.III"],"C","Compete ao Senado Federal aprovar previamente, por voto secreto, após arguição pública, a escolha de Ministros do Tribunal de Contas da União indicados pelo Presidente da República e de Governador de Território.","Art. 52, III, b e c.","competencia"),
(T5,["52.VI"],"C","Compete privativamente ao Senado Federal fixar, por proposta do Presidente da República, limites globais para o montante da dívida consolidada da União, dos Estados, do Distrito Federal e dos Municípios.","Art. 52, VI.","competencia"),
(T5,["52.VII"],"C","Compete privativamente ao Senado Federal dispor sobre limites globais e condições para as operações de crédito externo e interno da União, dos Estados, do Distrito Federal e dos Municípios.","Art. 52, VII.","competencia"),
(T5,["52.XI"],"C","Compete privativamente ao Senado Federal aprovar, por maioria absoluta e por voto secreto, a exoneração, de ofício, do Procurador-Geral da República antes do término de seu mandato.","Art. 52, XI.","quorum"),
(T5,["52.XI"],"E","A exoneração, de ofício, do Procurador-Geral da República antes do término de seu mandato é aprovada pelo Senado Federal por dois terços de seus membros.","Art. 52, XI: maioria absoluta e voto secreto.","quorum"),
(T5,["52.XV"],"C","Compete privativamente ao Senado Federal avaliar periodicamente a funcionalidade do Sistema Tributário Nacional e o desempenho das administrações tributárias.","Art. 52, XV.","competencia"),
(T5,["52.XIV"],"C","Compete privativamente ao Senado Federal eleger membros do Conselho da República, nos termos do art. 89, VII.","Art. 52, XIV.","competencia"),
(T5,["52.II"],"E","Compete privativamente à Câmara dos Deputados processar e julgar os Ministros do Supremo Tribunal Federal nos crimes de responsabilidade.","Art. 52, II: competência do Senado Federal.","competencia"),
# ---------- funcionamento, comissões e processo legislativo (complemento) ----------
(T5,["58"],"C","Às comissões, em razão da matéria de sua competência, cabe realizar audiências públicas com entidades da sociedade civil, convocar Ministros de Estado e receber petições, reclamações, representações ou queixas de qualquer pessoa contra atos ou omissões das autoridades ou entidades públicas.","Art. 58, §2º, II, III e IV.","competencia"),
(T5,["58"],"C","Às comissões cabe apreciar programas de obras, planos nacionais, regionais e setoriais de desenvolvimento e sobre eles emitir parecer.","Art. 58, §2º, VI.","competencia"),
(T5,["62"],"C","A deliberação de cada uma das Casas do Congresso Nacional sobre o mérito das medidas provisórias dependerá de juízo prévio sobre o atendimento de seus pressupostos constitucionais.","Art. 62, §5º.","leitura"),
(T5,["62"],"C","É vedada a edição de medidas provisórias sobre matéria relativa a organização do Poder Judiciário e do Ministério Público, a carreira e a garantia de seus membros.","Art. 62, §1º, I, c.","leitura"),
(T5,["62"],"C","É vedada a edição de medida provisória sobre matéria que vise a detenção ou sequestro de bens, de poupança popular ou qualquer outro ativo financeiro.","Art. 62, §1º, II.","leitura"),
(T5,["62"],"E","É vedada a edição de medida provisória sobre matéria já disciplinada em projeto de lei em tramitação no Congresso Nacional.","Art. 62, §1º, IV: matéria já disciplinada em projeto de lei aprovado pelo Congresso e pendente de sanção ou veto.","pegadinha"),
(T5,["62"],"E","As medidas provisórias que não forem convertidas em lei no prazo de sessenta dias perdem eficácia a partir da data em que se esgota esse prazo.","Art. 62, §3º: perdem eficácia desde a edição.","pegadinha"),
(T5,["62"],"C","Prorroga-se uma única vez por igual período a vigência de medida provisória que, no prazo de sessenta dias, contado de sua publicação, não tiver a sua votação encerrada nas duas Casas do Congresso Nacional.","Art. 62, §7º.","prazo"),
(T5,["64"],"C","A apreciação das emendas do Senado Federal pela Câmara dos Deputados, nos projetos com urgência solicitada pelo Presidente da República, far-se-á no prazo de dez dias.","Art. 64, §3º.","prazo"),
(T5,["64"],"E","Os prazos da urgência solicitada pelo Presidente da República correm também nos períodos de recesso do Congresso Nacional e aplicam-se aos projetos de código.","Art. 64, §4º: não correm no recesso nem se aplicam aos projetos de código.","pegadinha"),
(T5,["63"],"C","Não será admitido aumento da despesa prevista nos projetos sobre organização dos serviços administrativos da Câmara dos Deputados, do Senado Federal, dos Tribunais Federais e do Ministério Público.","Art. 63, II.","iniciativa"),
(T5,["44"],"E","O Poder Legislativo da União é exercido pela Câmara dos Deputados, com o auxílio do Senado Federal.","Art. 44: exercido pelo Congresso Nacional, que se compõe da Câmara e do Senado.","pegadinha"),
(T5,["60"],"C","A Constituição não poderá ser emendada na vigência de intervenção federal, de estado de defesa ou de estado de sítio, e a matéria constante de proposta de emenda rejeitada ou havida por prejudicada não pode ser objeto de nova proposta na mesma sessão legislativa.","Art. 60, §§1º e 5º.","leitura"),
# ---------- controle externo ----------
(T5,["71.II"],"C","Compete ao Tribunal de Contas da União julgar as contas dos administradores e demais responsáveis por dinheiros, bens e valores públicos da administração direta e indireta.","Art. 71, II.","competencia"),
(T5,["71.III"],"C","Compete ao Tribunal de Contas da União apreciar, para fins de registro, a legalidade dos atos de admissão de pessoal, excetuadas as nomeações para cargo de provimento em comissão, bem como a das concessões de aposentadorias, reformas e pensões.","Art. 71, III.","competencia"),
(T5,["71.III"],"E","Compete ao Tribunal de Contas da União apreciar, para fins de registro, a legalidade dos atos de admissão de pessoal, inclusive as nomeações para cargo de provimento em comissão.","Art. 71, III: excetuadas as nomeações para cargo em comissão.","pegadinha"),
(T5,["71.IV"],"C","Compete ao Tribunal de Contas da União realizar, por iniciativa própria, da Câmara dos Deputados, do Senado Federal, de comissão técnica ou de inquérito, inspeções e auditorias nas unidades administrativas dos Poderes Legislativo, Executivo e Judiciário.","Art. 71, IV.","competencia"),
(T5,["71.VI"],"C","Compete ao Tribunal de Contas da União fiscalizar a aplicação de quaisquer recursos repassados pela União, mediante convênio, acordo, ajuste ou outros instrumentos congêneres, a Estado, ao Distrito Federal ou a Município.","Art. 71, VI.","competencia"),
(T5,["71.IX"],"C","Verificada ilegalidade, o Tribunal de Contas da União assinará prazo para que o órgão ou entidade adote as providências necessárias ao exato cumprimento da lei e, se não atendido, sustará a execução do ato impugnado, comunicando a decisão à Câmara dos Deputados e ao Senado Federal.","Art. 71, IX e X.","competencia"),
(T5,["71"],"C","O Tribunal de Contas da União encaminhará ao Congresso Nacional, trimestral e anualmente, relatório de suas atividades.","Art. 71, §4º.","prazo"),
(T5,["72"],"C","A comissão mista permanente a que se refere o art. 166, §1º, diante de indícios de despesas não autorizadas, poderá solicitar à autoridade governamental responsável que, no prazo de cinco dias, preste os esclarecimentos necessários.","Art. 72, caput.","prazo"),
(T5,["72"],"E","Não prestados os esclarecimentos pela autoridade governamental, a comissão mista solicitará ao Tribunal de Contas pronunciamento conclusivo sobre a matéria, no prazo de sessenta dias.","Art. 72, §1º: trinta dias.","prazo"),
(T5,["72"],"C","Entendendo o Tribunal irregular a despesa, a comissão, se julgar que o gasto possa causar dano irreparável ou grave lesão à economia pública, proporá ao Congresso Nacional sua sustação.","Art. 72, §2º.","leitura"),
(T5,["73"],"C","Os Ministros do Tribunal de Contas da União serão nomeados dentre brasileiros com mais de trinta e cinco e menos de setenta anos de idade, idoneidade moral e reputação ilibada, notórios conhecimentos e mais de dez anos de exercício de função ou atividade profissional que exija esses conhecimentos.","Art. 73, §1º.","numero"),
(T5,["73"],"E","Os Ministros do Tribunal de Contas da União terão as mesmas garantias, prerrogativas, impedimentos, vencimentos e vantagens dos Ministros do Supremo Tribunal Federal.","Art. 73, §3º: dos Ministros do Superior Tribunal de Justiça.","competencia"),
(T5,["74.I"],"C","Os Poderes Legislativo, Executivo e Judiciário manterão, de forma integrada, sistema de controle interno com a finalidade de avaliar o cumprimento das metas previstas no plano plurianual, a execução dos programas de governo e dos orçamentos da União.","Art. 74, I.","leitura"),
(T5,["74"],"C","Os responsáveis pelo controle interno, ao tomarem conhecimento de qualquer irregularidade ou ilegalidade, dela darão ciência ao Tribunal de Contas da União, sob pena de responsabilidade solidária.","Art. 74, §1º.","leitura"),
(T5,["74"],"E","Os responsáveis pelo controle interno que tomarem conhecimento de irregularidade devem comunicá-la ao Ministério Público, sob pena de responsabilidade solidária.","Art. 74, §1º: ciência ao Tribunal de Contas da União.","competencia"),
# ---------- parlamentares: complemento ----------
(T6,["54"],"C","Desde a expedição do diploma, os Deputados e Senadores não poderão aceitar ou exercer cargo, função ou emprego remunerado, inclusive os de que sejam demissíveis ad nutum, nas entidades de direito público, autarquias, empresas públicas, sociedades de economia mista e empresas concessionárias de serviço público.","Art. 54, I, b.","leitura"),
(T6,["54"],"C","Desde a posse, os Deputados e Senadores não poderão ser proprietários, controladores ou diretores de empresa que goze de favor decorrente de contrato com pessoa jurídica de direito público, ou nela exercer função remunerada.","Art. 54, II, a.","leitura"),
(T6,["54"],"C","Desde a posse, os Deputados e Senadores não poderão patrocinar causa em que seja interessada qualquer das entidades referidas no art. 54, I, a.","Art. 54, II, c.","leitura"),
(T6,["55"],"C","Perderá o mandato o Deputado ou Senador que perder ou tiver suspensos os direitos políticos, ou quando o decretar a Justiça Eleitoral, nos casos previstos na Constituição.","Art. 55, IV e V.","leitura"),
(T6,["55"],"E","Perderá o mandato o Deputado ou Senador cujo procedimento for declarado incompatível com o decoro parlamentar por decisão da Mesa da respectiva Casa, de ofício.","Art. 55, II e §2º: decisão do Plenário, por maioria absoluta, mediante provocação da Mesa ou de partido político.","competencia"),
(T6,["56"],"C","Não perderá o mandato o Deputado ou Senador licenciado pela respectiva Casa por motivo de doença, ou para tratar, sem remuneração, de interesse particular, desde que, neste caso, o afastamento não ultrapasse cento e vinte dias por sessão legislativa.","Art. 56, II.","numero"),
(T6,["53"],"C","Desde a expedição do diploma, os membros do Congresso Nacional só podem ser presos em flagrante de crime inafiançável, devendo os autos ser remetidos, dentro de vinte e quatro horas, à Casa respectiva, que resolverá sobre a prisão pelo voto da maioria de seus membros.","Art. 53, §2º.","quorum"),
(T6,["53"],"E","A Casa respectiva poderá sustar o andamento da ação penal contra parlamentar, por crime ocorrido antes da diplomação, pelo voto da maioria de seus membros.","Art. 53, §3º: a sustação alcança crime ocorrido após a diplomação.","pegadinha"),
]
